{"dosyalar":{"logic.js":"function koordinatEsit(a, b) {
  return a && b && a.x === b.x && a.y === b.y;
}

function yonTersMi(a, b) {
  return a && b && a.x === -b.x && a.y === -b.y;
}

function durumKopyala(durum) {
  return {
    genislik: durum.genislik,
    yukseklik: durum.yukseklik,
    yilan: durum.yilan.map(function (parca) {
      return { x: parca.x, y: parca.y };
    }),
    yon: { x: durum.yon.x, y: durum.yon.y },
    yem: durum.yem ? { x: durum.yem.x, y: durum.yem.y } : null,
    oyunBitti: !!durum.oyunBitti
  };
}

function yonAyarla(durum, yeniYon) {
  if (!yeniYon || (yeniYon.x === 0 && yeniYon.y === 0)) {
    return durumKopyala(durum);
  }

  if (yonTersMi(durum.yon, yeniYon)) {
    return durumKopyala(durum);
  }

  var yeniDurum = durumKopyala(durum);
  yeniDurum.yon = { x: yeniYon.x, y: yeniYon.y };
  return yeniDurum;
}

function oyunBittiMi(durum) {
  var bas = durum.yilan[0];

  if (bas.x < 0 || bas.x >= durum.genislik || bas.y < 0 || bas.y >= durum.yukseklik) {
    return true;
  }

  for (var i = 1; i < durum.yilan.length; i += 1) {
    if (koordinatEsit(bas, durum.yilan[i])) {
      return true;
    }
  }

  return false;
}

function yemUret(durum, rastgeleSayiUret) {
  var bosHucereler = [];
  var x;
  var y;
  var i;
  var dolu;

  for (y = 0; y < durum.yukseklik; y += 1) {
    for (x = 0; x < durum.genislik; x += 1) {
      dolu = false;
      for (i = 0; i < durum.yilan.length; i += 1) {
        if (durum.yilan[i].x === x && durum.yilan[i].y === y) {
          dolu = true;
          break;
        }
      }
      if (!dolu) {
        bosHucereler.push({ x: x, y: y });
      }
    }
  }

  if (bosHucereler.length === 0) {
    return null;
  }

  var rastgeleFonksiyon = typeof rastgeleSayiUret === 'function' ? rastgeleSayiUret : Math.random;
  var index = Math.floor(rastgeleFonksiyon() * bosHucereler.length);

  if (index < 0) {
    index = 0;
  }
  if (index >= bosHucereler.length) {
    index = bosHucereler.length - 1;
  }

  return { x: bosHucereler[index].x, y: bosHucereler[index].y };
}

function tekAdim(durum, rastgeleSayiUret) {
  if (durum.oyunBitti) {
    return durumKopyala(durum);
  }

  var yeniDurum = durumKopyala(durum);
  var mevcutBas = yeniDurum.yilan[0];
  var yeniBas = {
    x: mevcutBas.x + yeniDurum.yon.x,
    y: mevcutBas.y + yeniDurum.yon.y
  };
  var yemYendi = yeniDurum.yem && koordinatEsit(yeniBas, yeniDurum.yem);

  yeniDurum.yilan.unshift(yeniBas);

  if (yemYendi) {
    yeniDurum.yem = yemUret(yeniDurum, rastgeleSayiUret);
  } else {
    yeniDurum.yilan.pop();
  }

  yeniDurum.oyunBitti = oyunBittiMi(yeniDurum);
  return yeniDurum;
}

function baslangicDurumuOlustur(genislik, yukseklik, rastgeleSayiUret) {
  var ortaX = Math.floor(genislik / 2);
  var ortaY = Math.floor(yukseklik / 2);
  var durum = {
    genislik: genislik,
    yukseklik: yukseklik,
    yilan: [
      { x: ortaX, y: ortaY },
      { x: ortaX - 1, y: ortaY },
      { x: ortaX - 2, y: ortaY }
    ],
    yon: { x: 1, y: 0 },
    yem: null,
    oyunBitti: false
  };

  durum.yem = yemUret(durum, rastgeleSayiUret);
  return durum;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    koordinatEsit,
    yonTersMi,
    durumKopyala,
    yonAyarla,
    oyunBittiMi,
    yemUret,
    tekAdim,
    baslangicDurumuOlustur
  };
}
","logic.test.js":"const { test } = require('node:test');
const assert = require('node:assert/strict');
const {
  oyunBittiMi,
  yemUret,
  tekAdim
} = require('./logic.js');

test('AC1: Yılan başı yem konumuna geldiğinde tekAdim() sonrası yılan uzunluğu 1 artar', () => {
  const durum = {
    genislik: 6,
    yukseklik: 6,
    yilan: [
      { x: 2, y: 2 },
      { x: 1, y: 2 },
      { x: 0, y: 2 }
    ],
    yon: { x: 1, y: 0 },
    yem: { x: 3, y: 2 },
    oyunBitti: false
  };

  const sonraki = tekAdim(durum, () => 0);

  assert.equal(sonraki.yilan.length, 4);
  assert.deepEqual(sonraki.yilan[0], { x: 3, y: 2 });
});

test('AC2: Yılan başı yem konumuna gelmediğinde tekAdim() sonrası yılan uzunluğu değişmez', () => {
  const durum = {
    genislik: 6,
    yukseklik: 6,
    yilan: [
      { x: 2, y: 2 },
      { x: 1, y: 2 },
      { x: 0, y: 2 }
    ],
    yon: { x: 1, y: 0 },
    yem: { x: 5, y: 5 },
    oyunBitti: false
  };

  const sonraki = tekAdim(durum, () => 0);

  assert.equal(sonraki.yilan.length, 3);
  assert.deepEqual(sonraki.yilan, [
    { x: 3, y: 2 },
    { x: 2, y: 2 },
    { x: 1, y: 2 }
  ]);
});

test('AC3: Yılan başı sınırın dışına çıktığında oyunBittiMi() true döner', () => {
  const solDisi = {
    genislik: 4,
    yukseklik: 4,
    yilan: [{ x: -1, y: 1 }, { x: 0, y: 1 }],
    yon: { x: -1, y: 0 },
    yem: { x: 2, y: 2 },
    oyunBitti: false
  };
  const sagDisi = {
    genislik: 4,
    yukseklik: 4,
    yilan: [{ x: 4, y: 1 }, { x: 3, y: 1 }],
    yon: { x: 1, y: 0 },
    yem: { x: 2, y: 2 },
    oyunBitti: false
  };
  const ustDisi = {
    genislik: 4,
    yukseklik: 4,
    yilan: [{ x: 1, y: -1 }, { x: 1, y: 0 }],
    yon: { x: 0, y: -1 },
    yem: { x: 2, y: 2 },
    oyunBitti: false
  };
  const altDisi = {
    genislik: 4,
    yukseklik: 4,
    yilan: [{ x: 1, y: 4 }, { x: 1, y: 3 }],
    yon: { x: 0, y: 1 },
    yem: { x: 2, y: 2 },
    oyunBitti: false
  };

  assert.equal(oyunBittiMi(solDisi), true);
  assert.equal(oyunBittiMi(sagDisi), true);
  assert.equal(oyunBittiMi(ustDisi), true);
  assert.equal(oyunBittiMi(altDisi), true);
});

test('AC4: Yılan başı gövdesindeki başka bir hücreyle aynı koordinata geldiğinde oyunBittiMi() true döner', () => {
  const durum = {
    genislik: 6,
    yukseklik: 6,
    yilan: [
      { x: 2, y: 2 },
      { x: 2, y: 3 },
      { x: 3, y: 3 },
      { x: 3, y: 2 },
      { x: 2, y: 2 }
    ],
    yon: { x: 0, y: -1 },
    yem: { x: 5, y: 5 },
    oyunBitti: false
  };

  assert.equal(oyunBittiMi(durum), true);
});

test('AC5: yemUret() yılanın kapladığı bir koordinatı hiçbir zaman döndürmez', () => {
  const durum = {
    genislik: 3,
    yukseklik: 3,
    yilan: [
      { x: 0, y: 0 },
      { x: 1, y: 0 },
      { x: 2, y: 0 },
      { x: 0, y: 1 },
      { x: 1, y: 1 },
      { x: 2, y: 1 },
      { x: 0, y: 2 },
      { x: 2, y: 2 }
    ],
    yon: { x: 1, y: 0 },
    yem: null,
    oyunBitti: false
  };

  const yem = yemUret(durum, () => 0);

  assert.deepEqual(yem, { x: 1, y: 2 });
  for (const parca of durum.yilan) {
    assert.notDeepEqual(yem, parca);
  }
});
","game.html":"<!DOCTYPE html>
<html lang="tr">
<head>
  <meta charset="UTF-8">
  <title>Snake</title>
  <style>
    body {
      margin: 0;
      font-family: Arial, sans-serif;
      background: #111;
      color: #eee;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      min-height: 100vh;
    }

    h1 {
      margin-bottom: 8px;
    }

    #info {
      margin-bottom: 12px;
    }

    canvas {
      background: #1b1b1b;
      border: 2px solid #444;
    }

    #yardim {
      margin-top: 12px;
      color: #bbb;
    }
  </style>
</head>
<body>
  <h1>Snake</h1>
  <div id="info">Skor: <span id="skor">0</span> <span id="durum"></span></div>
  <canvas id="oyun" width="400" height="400"></canvas>
  <div id="yardim">Ok tuşlarıyla yön değiştir. Oyun bitince R ile yeniden başlat.</div>

  <script src="logic.js"></script>
  <script>
    var hucreBoyutu = 20;
    var tahtaGenislik = 20;
    var tahtaYukseklik = 20;
    var canvas = document.getElementById('oyun');
    var ctx = canvas.getContext('2d');
    var skorEl = document.getElementById('skor');
    var durumEl = document.getElementById('durum');
    var zamanlayici = null;
    var durum = null;

    function yenidenBaslat() {
      durum = baslangicDurumuOlustur(tahtaGenislik, tahtaYukseklik);
      durumEl.textContent = '';
      skorGuncelle();
      ciz();
      if (zamanlayici !== null) {
        clearInterval(zamanlayici);
      }
      zamanlayici = setInterval(oyunDongusu, 140);
    }

    function skorGuncelle() {
      skorEl.textContent = String(durum.yilan.length - 3);
    }

    function oyunDongusu() {
      if (durum.oyunBitti) {
        if (zamanlayici !== null) {
          clearInterval(zamanlayici);
          zamanlayici = null;
        }
        durumEl.textContent = ' - Oyun bitti';
        ciz();
        return;
      }

      durum = tekAdim(durum);
      skorGuncelle();
      if (durum.oyunBitti) {
        durumEl.textContent = ' - Oyun bitti';
      }
      ciz();
    }

    function cizHucre(x, y, renk) {
      ctx.fillStyle = renk;
      ctx.fillRect(x * hucreBoyutu, y * hucreBoyutu, hucreBoyutu - 1, hucreBoyutu - 1);
    }

    function ciz() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = '#222';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      if (durum.yem) {
        cizHucre(durum.yem.x, durum.yem.y, '#ff5252');
      }

      for (var i = 0; i < durum.yilan.length; i += 1) {
        cizHucre(durum.yilan[i].x, durum.yilan[i].y, i === 0 ? '#7CFC00' : '#32CD32');
      }
    }

    document.addEventListener('keydown', function (event) {
      if (event.key === 'r' || event.key === 'R') {
        yenidenBaslat();
        return;
      }

      if (!durum || durum.oyunBitti) {
        return;
      }

      var yeniYon = null;

      if (event.key === 'ArrowUp') {
        yeniYon = { x: 0, y: -1 };
      } else if (event.key === 'ArrowDown') {
        yeniYon = { x: 0, y: 1 };
      } else if (event.key === 'ArrowLeft') {
        yeniYon = { x: -1, y: 0 };
      } else if (event.key === 'ArrowRight') {
        yeniYon = { x: 1, y: 0 };
      }

      if (yeniYon) {
        durum = yonAyarla(durum, yeniYon);
      }
    });

    yenidenBaslat();
  </script>
</body>
</html>
